mapper.select:
SELECT total.*, ( SELECT COUNT(*) FROM found_comment c WHERE c.num = total.num ) AS commentCount FROM ( /* 1) 유저 습득물 데이터 */ SELECT num, atc_id, id, clr_nm, dep_place, fd_filepath_img, fd_prdt_nm, fd_sbjt, fd_ymd, prdt_cl_nm, created_at, updated_at, done, is_deleted, view_count, 'user' AS dataSource FROM found WHERE is_deleted = 0 AND prdt_cl_nm IN #{item} AND fd_prdt_nm LIKE CONCAT('%', #{subCategory}, '%') AND clr_nm LIKE CONCAT('%', #{colorSelect}, '%') AND fd_ymd >= STR_TO_DATE(CONCAT(#{startDate}, ' 00:00:00'), '%Y-%m-%d %H:%i:%s') AND fd_ymd <= STR_TO_DATE(CONCAT(#{endDate}, ' 23:59:59'), '%Y-%m-%d %H:%i:%s') AND id LIKE CONCAT('%', #{author}, '%') AND done = 0AND done = 1 AND fd_prdt_nm LIKE CONCAT('%', #{keyword}, '%')
UNION ALL
/* 2) 경찰청 습득물 데이터 */ SELECT num, atc_id, id, clr_nm, dep_place, fd_filepath_img, fd_prdt_nm, fd_sbjt, fd_ymd, prdt_cl_nm, created_at, updated_at, done, is_deleted, view_count, 'police' AS dataSource FROM found_police WHERE is_deleted = 0 AND prdt_cl_nm IN #{item} AND fd_prdt_nm LIKE CONCAT('%', #{subCategory}, '%') AND clr_nm LIKE CONCAT('%', #{colorSelect}, '%') AND fd_ymd >= STR_TO_DATE(CONCAT(#{startDate}, ' 00:00:00'), '%Y-%m-%d %H:%i:%s') AND fd_ymd <= STR_TO_DATE(CONCAT(#{endDate}, ' 23:59:59'), '%Y-%m-%d %H:%i:%s') AND id LIKE CONCAT('%', #{author}, '%') AND done = 0AND done = 1 AND fd_prdt_nm LIKE CONCAT('%', #{keyword}, '%')
UNION ALL
/* 3) 포털 습득물 데이터 */ SELECT num, atc_id, id, clr_nm, dep_place, fd_filepath_img, fd_prdt_nm, fd_sbjt, fd_ymd, prdt_cl_nm, created_at, updated_at, done, is_deleted, view_count, 'portal' AS dataSource FROM found_portal WHERE is_deleted = 0 AND prdt_cl_nm IN #{item} AND fd_prdt_nm LIKE CONCAT('%', #{subCategory}, '%') AND clr_nm LIKE CONCAT('%', #{colorSelect}, '%') AND fd_ymd >= STR_TO_DATE(CONCAT(#{startDate}, ' 00:00:00'), '%Y-%m-%d %H:%i:%s') AND fd_ymd <= STR_TO_DATE(CONCAT(#{endDate}, ' 23:59:59'), '%Y-%m-%d %H:%i:%s') AND id LIKE CONCAT('%', #{author}, '%') AND done = 0AND done = 1 AND fd_prdt_nm LIKE CONCAT('%', #{keyword}, '%') ) total
ORDER BY total.fd_ymd ASC ORDER BY total.fd_ymd DESC
LIMIT #{paging.offset}, #{paging.size}

