WHERE atc_id =#{atcId}

mapper.select:
SELECT combined_found.*, combined_found.dataSource, f.id AS file_id, f.atc_id AS file_atc_id, f.fd_filepath_img AS file_filepath_img, f.save_name, f.file_size, f.file_path FROM ( SELECT num, atc_id, id, dep_place, fd_filepath_img, fd_prdt_nm, fd_sbjt, fd_ymd, prdt_cl_nm, clr_nm, created_at, updated_at, done, is_deleted, view_count, 'user' AS dataSource FROM found WHERE is_deleted = 0 And atc_id = #{atcId}
UNION ALL
SELECT num, atc_id, id, dep_place, fd_filepath_img, fd_prdt_nm, fd_sbjt, fd_ymd, prdt_cl_nm, clr_nm, created_at, updated_at, done, is_deleted, view_count, 'police' AS dataSource FROM found_police WHERE is_deleted = 0 And atc_id = #{atcId}
UNION ALL
SELECT num, atc_id, id, dep_place, fd_filepath_img, fd_prdt_nm, fd_sbjt, fd_ymd, prdt_cl_nm, clr_nm, created_at, updated_at, done, is_deleted, view_count, 'portal' AS dataSource FROM found_portal WHERE is_deleted = 0 And atc_id = #{atcId} ) combined_found LEFT JOIN found_file f on combined_found.atc_id=f.atc_id ORDER BY f.id ASC

